     int count = arrlen(root);
+
+    text_begin_frame();
+    for (int i = 0; i < count; i++) {
+        cache_glyphs(root[i]);
+    }
+    text_upload_pages();
+
     for (int i = 0; i < count; i++) {
         if (root[i]) {
             render_instance(root[i], ctx);
